// Synthetic manifest lookup (V01-R7, ADR 0014). The entries are a build resource
// generated by build-synthetic-manifest.ts and committed; this module reads
// nothing else, so no data folder, environment variable or setting can add one.
import { createHash } from "node:crypto";
import entries from "./synthetic-manifest.json" with { type: "json" };

/** One hash over title and body together; JSON array encoding keeps the boundary. */
export function syntheticHash(title: string, body: string): string {
  return createHash("sha256")
    .update(JSON.stringify([title, body]))
    .digest("hex");
}

const byHash: ReadonlyMap<string, Readonly<{ malicious: boolean }>> = new Map(
  entries.map((e) => [e.hash, Object.freeze({ malicious: e.malicious })]),
);

/** The manifest entry for exactly this title and body, or undefined if not synthetic. */
export function lookupSynthetic(
  title: string,
  body: string,
): Readonly<{ malicious: boolean }> | undefined {
  return byHash.get(syntheticHash(title, body));
}
